-- Simplification (simplify-2026-11): DDL generated by drizzle-kit, plus the
-- data steps each change needs, ordered so every step runs while the columns
-- it reads still exist.

-- Roles collapse to owner|member.
UPDATE `org_members` SET `role` = 'owner' WHERE `role` = 'admin';--> statement-breakpoint
UPDATE `org_members` SET `role` = 'member' WHERE `role` = 'viewer';--> statement-breakpoint
-- Custom Dockerfile images are gone; only seed and registered images remain.
DELETE FROM `images` WHERE `provenance` = 'dockerfile';--> statement-breakpoint
-- organizations.personal: 'true'/'false' text -> 1/0 (copied as integers by
-- the table rebuild below).
UPDATE `organizations` SET `personal` = CASE `personal` WHEN 'true' THEN 1 ELSE 0 END;--> statement-breakpoint

ALTER TABLE `settings` RENAME TO `server_config`;--> statement-breakpoint
ALTER TABLE `entity_toolbox_versions` RENAME TO `toolbox_versions`;--> statement-breakpoint
ALTER TABLE `entity_toolboxes` RENAME TO `toolboxes`;--> statement-breakpoint
ALTER TABLE `toolboxes` RENAME COLUMN "owner_id" TO "org_id";--> statement-breakpoint
CREATE TABLE `agent_tasks` (
	`id` text PRIMARY KEY NOT NULL,
	`owner_id` text NOT NULL,
	`sandbox_id` text NOT NULL,
	`session_id` text NOT NULL,
	`cwd` text NOT NULL,
	`harness` text NOT NULL,
	`status` text NOT NULL,
	`title` text NOT NULL,
	`source` text NOT NULL,
	`turn_count` integer NOT NULL,
	`last_prompt` text NOT NULL,
	`last_reply` text NOT NULL,
	`last_error` text,
	`result` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL
);
--> statement-breakpoint
CREATE INDEX `idx_agent_tasks_owner` ON `agent_tasks` (`owner_id`);--> statement-breakpoint
CREATE INDEX `idx_agent_tasks_sandbox` ON `agent_tasks` (`sandbox_id`);--> statement-breakpoint
DROP TABLE `integration_connections`;--> statement-breakpoint
DROP INDEX `idx_entity_toolbox_versions_toolbox`;--> statement-breakpoint
CREATE INDEX `idx_toolbox_versions_toolbox` ON `toolbox_versions` (`toolbox_id`);--> statement-breakpoint
DROP INDEX `idx_entity_toolboxes_owner`;--> statement-breakpoint
DROP INDEX `idx_entity_toolboxes_owner_slug`;--> statement-breakpoint

-- Toolboxes are org-owned only: a user-owned toolbox moves to its owner's
-- personal org. A slug already taken there gets a short id suffix first.
UPDATE `toolboxes`
SET `slug` = substr(`slug`, 1, 40) || '-' || lower(substr(`id`, 1, 8))
WHERE `owner_type` = 'user' AND EXISTS (
  SELECT 1 FROM `toolboxes` AS `o`
  JOIN `users` AS `u` ON `u`.`id` = `toolboxes`.`org_id`
  WHERE `o`.`owner_type` = 'org'
    AND `o`.`org_id` = `u`.`personal_org_id`
    AND `o`.`slug` = `toolboxes`.`slug`
);--> statement-breakpoint
UPDATE `toolboxes`
SET `org_id` = (SELECT `personal_org_id` FROM `users` WHERE `users`.`id` = `toolboxes`.`org_id`),
    `owner_type` = 'org'
WHERE `owner_type` = 'user'
  AND (SELECT `personal_org_id` FROM `users` WHERE `users`.`id` = `toolboxes`.`org_id`) IS NOT NULL;--> statement-breakpoint
ALTER TABLE `toolboxes` ADD `files` text;--> statement-breakpoint
ALTER TABLE `toolboxes` DROP COLUMN `owner_type`;--> statement-breakpoint

-- Org policy -> an auto-inject `org-defaults` toolbox per org carrying the
-- policy's files, processes, ports and harness. Policy hooks have no toolbox
-- equivalent and are dropped.
INSERT INTO `toolboxes` (`id`, `org_id`, `slug`, `description`, `build`, `paths`, `harness`, `processes`, `ports`, `files`, `auto_inject`, `refresh_steps`, `created_at`, `updated_at`)
SELECT lower(hex(randomblob(6))), `p`.`org_id`, 'org-defaults',
  'Files and settings every sandbox in this org gets (migrated from the org policy)',
  '[]', '[]',
  json_extract(`p`.`fragment`, '$.harness'),
  json_extract(`p`.`fragment`, '$.processes'),
  json_extract(`p`.`fragment`, '$.ports'),
  json_extract(`p`.`fragment`, '$.files'),
  1, '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM `org_policy_specs` AS `p`
WHERE (json_extract(`p`.`fragment`, '$.files') IS NOT NULL
    OR json_extract(`p`.`fragment`, '$.processes') IS NOT NULL
    OR json_extract(`p`.`fragment`, '$.ports') IS NOT NULL
    OR json_extract(`p`.`fragment`, '$.harness') IS NOT NULL)
  AND NOT EXISTS (SELECT 1 FROM `toolboxes` AS `t` WHERE `t`.`org_id` = `p`.`org_id` AND `t`.`slug` = 'org-defaults');--> statement-breakpoint
DROP TABLE `org_policy_specs`;--> statement-breakpoint
CREATE INDEX `idx_toolboxes_org` ON `toolboxes` (`org_id`);--> statement-breakpoint
CREATE UNIQUE INDEX `idx_toolboxes_org_slug` ON `toolboxes` (`org_id`,`slug`);--> statement-breakpoint

PRAGMA foreign_keys=OFF;--> statement-breakpoint
CREATE TABLE `__new_organizations` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`avatar_url` text,
	`personal` integer DEFAULT false NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL
);
--> statement-breakpoint
INSERT INTO `__new_organizations`("id", "name", "slug", "avatar_url", "personal", "created_at", "updated_at") SELECT "id", "name", "slug", "avatar_url", CAST("personal" AS integer), "created_at", "updated_at" FROM `organizations`;--> statement-breakpoint
DROP TABLE `organizations`;--> statement-breakpoint
ALTER TABLE `__new_organizations` RENAME TO `organizations`;--> statement-breakpoint
PRAGMA foreign_keys=ON;--> statement-breakpoint
CREATE UNIQUE INDEX `organizations_slug_unique` ON `organizations` (`slug`);--> statement-breakpoint

ALTER TABLE `sandboxes` ADD `image` text;--> statement-breakpoint
ALTER TABLE `sandboxes` DROP COLUMN `pod_name`;--> statement-breakpoint
ALTER TABLE `sandboxes` DROP COLUMN `pvc_name`;--> statement-breakpoint
ALTER TABLE `snapshots` ADD `kind` text DEFAULT 'manual' NOT NULL;--> statement-breakpoint
ALTER TABLE `snapshots` ADD `repo_heads` text;--> statement-breakpoint
ALTER TABLE `images` DROP COLUMN `dockerfile`;--> statement-breakpoint
ALTER TABLE `toolsets` DROP COLUMN `env`;--> statement-breakpoint

-- snapshots.kind backfill: real prebuilds carry a spec; the snapshot a paused
-- sandbox resumes from is a pause snapshot; a fork copy's own boot source is a
-- fork snapshot. Everything else stays 'manual' (orphaned old pause snapshots
-- land there and age out under snapshot.manualKeep).
UPDATE `snapshots` SET `kind` = 'prebuild' WHERE `spec` IS NOT NULL;--> statement-breakpoint
UPDATE `snapshots` SET `kind` = 'pause'
WHERE `spec` IS NULL
  AND `ref` IN (SELECT `pause_snapshot_ref` FROM `sandboxes` WHERE `pause_snapshot_ref` IS NOT NULL);--> statement-breakpoint
UPDATE `snapshots` SET `kind` = 'fork'
WHERE `spec` IS NULL AND `kind` = 'manual' AND `sandbox_id` IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM `sandboxes` AS `s`
    WHERE `s`.`id` = `snapshots`.`sandbox_id`
      AND json_extract(`s`.`spec`, '$.source.snapshot') = `snapshots`.`ref`
  );--> statement-breakpoint
-- sandboxes.image backfill: from the source snapshot, else a fully-qualified
-- image source. Rows left NULL resolve their source at first use.
UPDATE `sandboxes` SET `image` = (
  SELECT `image` FROM `snapshots`
  WHERE `snapshots`.`ref` = json_extract(`sandboxes`.`spec`, '$.source.snapshot')
)
WHERE json_extract(`spec`, '$.source.snapshot') IS NOT NULL;--> statement-breakpoint
UPDATE `sandboxes` SET `image` = json_extract(`spec`, '$.source.image')
WHERE `image` IS NULL
  AND (json_extract(`spec`, '$.source.image') LIKE '%/%'
    OR json_extract(`spec`, '$.source.image') LIKE '%@%');--> statement-breakpoint

-- Frak's deployment (a no-op anywhere these rows don't exist): `frak` was
-- KONFeature's personal org acting as the team org. It becomes a real team
-- org (`auth.defaultOrg: frak`) and KONFeature gets a personal org.
INSERT INTO `organizations` (`id`, `name`, `slug`, `personal`, `created_at`, `updated_at`)
SELECT lower(hex(randomblob(6))), `u`.`username`, lower(`u`.`username`), 1,
  strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM `users` AS `u`
JOIN `organizations` AS `o` ON `o`.`id` = `u`.`personal_org_id`
WHERE `u`.`username` = 'KONFeature' AND `o`.`slug` = 'frak'
  AND NOT EXISTS (SELECT 1 FROM `organizations` WHERE `slug` = lower(`u`.`username`));--> statement-breakpoint
INSERT INTO `org_members` (`id`, `org_id`, `user_id`, `role`, `joined_at`)
SELECT lower(hex(randomblob(6))), `o`.`id`, `u`.`id`, 'owner', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM `users` AS `u`
JOIN `organizations` AS `o` ON `o`.`slug` = 'konfeature' AND `o`.`personal` = 1
WHERE `u`.`username` = 'KONFeature'
  AND `u`.`personal_org_id` = (SELECT `id` FROM `organizations` WHERE `slug` = 'frak')
  AND NOT EXISTS (SELECT 1 FROM `org_members` AS `m` WHERE `m`.`org_id` = `o`.`id` AND `m`.`user_id` = `u`.`id`);--> statement-breakpoint
UPDATE `users`
SET `personal_org_id` = (SELECT `id` FROM `organizations` WHERE `slug` = 'konfeature' AND `personal` = 1)
WHERE `username` = 'KONFeature'
  AND `personal_org_id` = (SELECT `id` FROM `organizations` WHERE `slug` = 'frak')
  AND EXISTS (SELECT 1 FROM `organizations` WHERE `slug` = 'konfeature' AND `personal` = 1);--> statement-breakpoint
UPDATE `organizations` SET `personal` = 0
WHERE `slug` = 'frak'
  AND NOT EXISTS (
    SELECT 1 FROM `users` AS `u`
    WHERE `u`.`personal_org_id` = `organizations`.`id`
  );
